const fs = require('fs');
const outputDir = $('Code: Create Output Folder').item.json.outputDir;
const datePrefix = $('Code: Create Output Folder').item.json.datePrefix;
const body = $input.first().json;
// When /ingest succeeds, body is the chunks-written response and error is absent.
if (body && typeof body.chunks_written === 'number') {
  return { json: { ...body, ingest_status: 'ok', datePrefix, outputDir } };
}
// Otherwise treat as failure. n8n puts errors on $input.first().error when
// onError=continueRegularOutput; the shape varies by n8n version, so cover both.
const err = ($input.first().error) || { message: 'Non-success response', response: body };
const ts = new Date().toISOString();
const report = `[${ts}] /ingest failed after retry\nstatus: ${err.httpCode || 'n/a'}\nmessage: ${err.message || JSON.stringify(err)}\nresponse: ${JSON.stringify(err.response || body || {}, null, 2)}\n`;
fs.writeFileSync(`${outputDir}/ingest-error.log`, report, 'utf8');
return { json: { ingest_status: 'failed', ingest_error: err.message || 'unknown', datePrefix, outputDir } };
